package io.github.diodeme.ji.session.tree;

import com.fasterxml.jackson.databind.ObjectMapper;
import com.fasterxml.jackson.datatype.jdk8.Jdk8Module;
import com.fasterxml.jackson.datatype.jsr310.JavaTimeModule;
import java.io.IOException;

/** Strict JSON encoding of the canonical Session document. */
public final class JacksonSessionCodec implements SessionCodec {
    private final ObjectMapper mapper;

    public JacksonSessionCodec() {
        mapper = new ObjectMapper()
                .registerModule(new Jdk8Module())
                .registerModule(new JavaTimeModule());
    }

    @Override
    public byte[] encode(SessionDocument document) {
        try {
            return mapper.writeValueAsBytes(document);
        } catch (IOException exception) {
            throw new IllegalStateException("Session document cannot be encoded", exception);
        }
    }

    @Override
    public SessionDocument decode(byte[] encoded) {
        try {
            return mapper.readValue(encoded, SessionDocument.class);
        } catch (IOException | RuntimeException exception) {
            throw new IllegalStateException("Session document cannot be decoded", exception);
        }
    }
}
